"use client";
/* Fish, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Fish(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("fish"); }, []);
  return React.createElement("piix-pal", { "pal": "fish", ...piixAttrs(props) });
}

export default Fish;
